9. // --- CMIS_STATE_* (common.py:23) --------------------------------------------------
10. pub const CMIS_STATE_UNKNOWN: &str = "UNKNOWN";
11. pub const CMIS_STATE_INSERTED: &str = "INSERTED";
12. pub const CMIS_STATE_DP_PRE_INIT_CHECK: &str = "DP_PRE_INIT_CHECK";
13. pub const CMIS_STATE_DP_DEINIT: &str = "DP_DEINIT";
14. pub const CMIS_STATE_AP_CONF: &str = "AP_CONFIGURED";
15. pub const CMIS_STATE_DP_ACTIVATE: &str = "DP_ACTIVATION";
16. pub const CMIS_STATE_DP_INIT: &str = "DP_INIT";
17. pub const CMIS_STATE_DP_TXON: &str = "DP_TXON";
18. pub const CMIS_STATE_READY: &str = "READY";
19. pub const CMIS_STATE_REMOVED: &str = "REMOVED";
20. pub const CMIS_STATE_FAILED: &str = "FAILED";
21. 
22. /// `CMIS_TERMINAL_STATES` (common.py:35).
23. pub const CMIS_TERMINAL_STATES: &[&str] = &[CMIS_STATE_READY, CMIS_STATE_FAILED, CMIS_STATE_REMOVED];
24. 
25. /// `NOT_IMPLEMENTED_ERROR` sys-exit code (analysis §3.5).
26. pub const NOT_IMPLEMENTED_ERROR: i32 = 3;
