28. /// Typed CMIS state (mirrors the `CMIS_STATE_*` string constants). The string form
29. /// is what is stored in `TRANSCEIVER_STATUS_SW.cmis_state`.
30. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
31. pub enum CmisState {
32.     Unknown,
33.     Inserted,
34.     DpPreInitCheck,
35.     DpDeinit,
36.     ApConfigured,
37.     DpActivation,
38.     DpInit,
39.     DpTxOn,
40.     Ready,
41.     Removed,
42.     Failed,
43. }
44. 
45. impl CmisState {
46.     /// String form written to STATE_DB.
47.     pub fn as_str(&self) -> &'static str {
48.         match self {
49.             CmisState::Unknown => CMIS_STATE_UNKNOWN,
50.             CmisState::Inserted => CMIS_STATE_INSERTED,
51.             CmisState::DpPreInitCheck => CMIS_STATE_DP_PRE_INIT_CHECK,
52.             CmisState::DpDeinit => CMIS_STATE_DP_DEINIT,
53.             CmisState::ApConfigured => CMIS_STATE_AP_CONF,
54.             CmisState::DpActivation => CMIS_STATE_DP_ACTIVATE,
55.             CmisState::DpInit => CMIS_STATE_DP_INIT,
56.             CmisState::DpTxOn => CMIS_STATE_DP_TXON,
57.             CmisState::Ready => CMIS_STATE_READY,
58.             CmisState::Removed => CMIS_STATE_REMOVED,
59.             CmisState::Failed => CMIS_STATE_FAILED,
60.         }
61.     }
62. 
63.     /// `state in CMIS_TERMINAL_STATES`.
64.     pub fn is_terminal(&self) -> bool {
65.         matches!(self, CmisState::Ready | CmisState::Failed | CmisState::Removed)
66.     }
67. 
68.     /// Parse the `TRANSCEIVER_STATUS_SW.cmis_state` string; unknown → `Unknown`.
69.     pub fn from_db_str(s: &str) -> CmisState {
70.         match s {
71.             CMIS_STATE_INSERTED => CmisState::Inserted,
72.             CMIS_STATE_DP_PRE_INIT_CHECK => CmisState::DpPreInitCheck,
73.             CMIS_STATE_DP_DEINIT => CmisState::DpDeinit,
74.             CMIS_STATE_AP_CONF => CmisState::ApConfigured,
75.             CMIS_STATE_DP_ACTIVATE => CmisState::DpActivation,
76.             CMIS_STATE_DP_INIT => CmisState::DpInit,
77.             CMIS_STATE_DP_TXON => CmisState::DpTxOn,
78.             CMIS_STATE_READY => CmisState::Ready,
79.             CMIS_STATE_REMOVED => CmisState::Removed,
80.             CMIS_STATE_FAILED => CmisState::Failed,
81.             _ => CmisState::Unknown,
82.         }
83.     }
84. }
