86. /// `update_port_transceiver_status_table_sw` — set `status`/`error` on STATUS_SW.
87. ///
88. /// Mirrors `common.update_port_transceiver_status_table_sw`: it writes the SW-owned
89. /// `{status, error}` pair via `Table.set`. The reference passes `error_descriptions`
90. /// defaulting to `'N/A'`; callers here pass it explicitly. On the real STATE_DB this
91. /// is an additive merge, so it never clobbers the CMIS-owned `cmis_state` field
92. /// another writer set (see [`crate::db`]).
93. pub fn update_port_transceiver_status_table_sw(
94.     logical_port_name: &str,
95.     status_sw_tbl: &dyn DbTable,
96.     status: &str,
97.     error: &str,
98. ) {
99.     status_sw_tbl.set(
100.         logical_port_name,
101.         &[
102.             ("status".to_string(), status.to_string()),
103.             ("error".to_string(), error.to_string()),
104.         ],
105.     );
106. }
107. 
108. /// `get_cmis_state_from_state_db(lport, status_sw_tbl)` → the stored `cmis_state`.
109. pub fn get_cmis_state_from_state_db(lport: &str, status_sw_tbl: &dyn DbTable) -> String {
110.     // Mirror common.get_cmis_state_from_state_db: the port's `cmis_state`, or
111.     // `UNKNOWN` when the field is absent (treated as a transitional/non-terminal state).
112.     status_sw_tbl
113.         .hget(lport, "cmis_state")
114.         .unwrap_or_else(|| CMIS_STATE_UNKNOWN.to_string())
115. }
116. 
117. /// `del_port_sfp_dom_info_from_db` — delete a port's rows across the given tables.
118. ///
119. /// Mirrors `common.del_port_sfp_dom_info_from_db`: for a (non-ganged) logical port
120. /// the physical port name equals the logical name, so this deletes `<lport>` from
121. /// every supplied table handle. `None` handles are filtered by the caller (the
122. /// reference passes `intf_tbl=None` in `deinit` to keep `TRANSCEIVER_INFO`).
123. pub fn del_port_sfp_dom_info_from_db(logical_port_name: &str, tables: &[&dyn DbTable]) {
124.     for tbl in tables {
125.         tbl.del(logical_port_name);
126.     }
127. }
