129. /// `is_fast_reboot_enabled()` — STATE_DB `FAST_RESTART_ENABLE_TABLE` gate.
130. ///
131. /// Mirrors `common.is_fast_reboot_enabled`, which reads
132. /// `FAST_RESTART_ENABLE_TABLE|system` field `enable` and returns `"true" in <value>`
133. /// (a substring test, so any value containing `true` — e.g. `"true"` — enables it).
134. /// The reference shells out to `sonic-db-cli`; here the caller passes the
135. /// `FAST_RESTART_ENABLE_TABLE` handle so the read goes through the [`DbTable`] seam.
136. /// An absent row/field (or a value without `true`) means fast reboot is NOT enabled.
137. pub fn is_fast_reboot_enabled(fast_restart_enable_tbl: &dyn DbTable) -> bool {
138.     fast_restart_enable_tbl
139.         .hget("system", "enable")
140.         .map(|v| v.contains("true"))
141.         .unwrap_or(false)
142. }
