150. /// `get_interface_speed(ifname)` (common.py:193) — map a CMIS host-electrical-interface
151. /// name to the host port speed in Mbps, or `0` when it matches no known family. The
152. /// order of the checks matters (broad substrings last); mirror the reference exactly.
153. pub fn get_interface_speed(ifname: &str) -> u32 {
154.     if ifname.contains("1.6T") {
155.         1_600_000
156.     } else if ifname.contains("800G") {
157.         800_000
158.     } else if ifname.contains("400G") {
159.         400_000
160.     } else if ifname.contains("200G") {
161.         200_000
162.     } else if ifname.contains("100G") || ifname.contains("CAUI-4") {
163.         100_000
164.     } else if ifname.contains("50G") || ifname.contains("LAUI-2") {
165.         50_000
166.     } else if ifname.contains("40G") || ifname.contains("XLAUI") || ifname.contains("XLPPI") {
167.         40_000
168.     } else if ifname.contains("25G") {
169.         25_000
170.     } else if ifname.contains("10G") || ifname.contains("SFI") || ifname.contains("XFI") {
171.         10_000
172.     } else if ifname.contains("1000BASE") {
173.         1_000
174.     } else {
175.         0
176.     }
177. }
