179. /// `get_cmis_application_desired(api, host_lane_count, speed)` (common.py:228) — pick the
180. /// module application code whose advertisement entry matches the requested host lane
181. /// count + speed. `app_advert` is `api.get_application_advertisement()` marshalled to a
182. /// JSON object keyed by the (stringified) app index; CMIS decode stays in Python. Returns
183. /// `None` when `speed`/`host_lane_count` is 0 or no advertised app matches (the reference
184. /// `return None`). The apps are scanned in ascending numeric index order (the reference
185. /// builds `ret[app]` for `app in range(1, 16)`), and the returned code is `index & 0xf`.
186. pub fn get_cmis_application(host_lane_count: u32, speed: u32, app_advert: &serde_json::Value) -> Option<u32> {
187.     if speed == 0 || host_lane_count == 0 {
188.         return None;
189.     }
190.     let map = app_advert.as_object()?;
191.     // Numeric-ascending scan to match Python dict insertion order (apps 1..15).
192.     let mut entries: Vec<(u32, &serde_json::Value)> = map
193.         .iter()
194.         .filter_map(|(k, v)| k.parse::<u32>().ok().map(|idx| (idx, v)))
195.         .collect();
196.     entries.sort_by_key(|(idx, _)| *idx);
197.     for (index, app_info) in entries {
198.         let advert_lane_count = app_info.get("host_lane_count").and_then(|v| v.as_u64());
199.         let ifname = app_info
200.             .get("host_electrical_interface_id")
201.             .and_then(|v| v.as_str())
202.             .unwrap_or("");
203.         if advert_lane_count == Some(host_lane_count as u64) && get_interface_speed(ifname) == speed {
204.             return Some(index & 0xf);
205.         }
206.     }
207.     None
208. }
