210. /// `_wrapper_get_presence(sfp)` — fold the platform presence shim into the HAL seam.
211. ///
212. /// The reference `common._wrapper_get_presence(physical_port)` calls
213. /// `platform_chassis.get_sfp(physical_port).get_presence()` and falls back to `False`
214. /// on `NotImplementedError`. Here the caller has already resolved the [`SfpHandle`]
215. /// via the HAL; a read error degrades to `false` exactly like the Python fallback.
216. pub fn wrapper_get_presence(sfp: &dyn SfpHandle) -> Result<bool> {
217.     Ok(sfp.get_presence().unwrap_or(false))
218. }
219. 
220. /// `get_physical_port_name(logical_port, physical_port, ganged)` (common.py:268) — a
221. /// ganged (breakout-fanout) member is suffixed `":{member} (ganged)"`, otherwise the
222. /// logical port name is used verbatim.
223. pub fn get_physical_port_name(logical_port: &str, physical_port: usize, ganged: bool) -> String {
224.     if ganged {
225.         format!("{logical_port}:{physical_port} (ganged)")
226.     } else {
227.         logical_port.to_string()
228.     }
229. }
230. 
231. /// `get_physical_port_name_dict(logical_port_name, port_mapping)` (common.py:275) — map
232. /// each physical port backing `logical_port_name` to its display name. A logical port
233. /// with more than one physical port is *ganged*, so each member gets the `(ganged)`
234. /// suffix keyed by a 1-based member index; a single-port logical port maps to just its
235. /// name. An unknown logical port yields an empty map. The result is ordered
236. /// (`BTreeMap`) so ganged member numbering is stable.
237. pub fn get_physical_port_name_dict(
238.     logical_port_name: &str,
239.     port_mapping: &crate::xcvrd_utilities::port_event_helper::PortMapping,
240. ) -> std::collections::BTreeMap<usize, String> {
241.     let mut port_name_dict = std::collections::BTreeMap::new();
242.     let Some(physical_port_list) =
243.         port_mapping.logical_port_name_to_physical_port_list(logical_port_name)
244.     else {
245.         return port_name_dict;
246.     };
247.     let ganged_port = physical_port_list.len() > 1;
248.     let mut ganged_member_num = 1;
249.     for physical_port in physical_port_list {
250.         let port_name = get_physical_port_name(logical_port_name, ganged_member_num, ganged_port);
251.         ganged_member_num += 1;
252.         port_name_dict.insert(physical_port, port_name);
253.     }
254.     port_name_dict
255. }
256. 
257. /// `check_port_in_range(range_str, physical_port)` (common.py:350) — is `physical_port`
258. /// within the inclusive `"<start>-<end>"` range? The reference splits on `-` and
259. /// `int()`s both ends (callers only pass a string that contains `-`). A malformed range
260. /// (missing separator / non-numeric bound) degrades to `false` here rather than raising,
261. /// keeping the media/optics SI parse resilient.
262. pub fn check_port_in_range(range_str: &str, physical_port: i64) -> bool {
263.     let mut parts = range_str.splitn(2, '-');
264.     let (Some(start_str), Some(end_str)) = (parts.next(), parts.next()) else {
265.         return false;
266.     };
267.     match (start_str.trim().parse::<i64>(), end_str.trim().parse::<i64>()) {
268.         (Ok(start), Ok(end)) => start <= physical_port && physical_port <= end,
269.         _ => false,
270.     }
271. }
272. 
273. /// Python `re.match(pattern, text)` — anchored at the START only (not the end). An
274. /// invalid pattern degrades to `false` (the media parser has no `try/except`, but a
275. /// bad config key must not crash the daemon). Uses a backtracking engine so the
276. /// media_settings.json keys that use negative lookahead match as they do in Python.
277. pub fn regex_match(pattern: &str, text: &str) -> bool {
278.     match fancy_regex::Regex::new(&format!("^(?:{pattern})")) {
279.         Ok(re) => re.is_match(text).unwrap_or(false),
280.         Err(_) => false,
281.     }
282. }
283. 
284. /// Python `re.fullmatch(pattern, text)` — anchored at BOTH ends. `Err(())` mirrors
285. /// `re.error` (an invalid pattern) so callers that emulate the Python `try/except`
286. /// fall back to exact string comparison (see `optics_si_parser::_match_optics_si_key`).
287. pub fn regex_fullmatch_checked(pattern: &str, text: &str) -> std::result::Result<bool, ()> {
288.     match fancy_regex::Regex::new(&format!("^(?:{pattern})$")) {
289.         Ok(re) => Ok(re.is_match(text).unwrap_or(false)),
290.         Err(_) => Err(()),
291.     }
292. }
293. 
294. /// Python `re.fullmatch(pattern, text)` where an invalid pattern is treated as no-match
295. /// (the media lane-speed matching has no `try/except`).
296. pub fn regex_fullmatch(pattern: &str, text: &str) -> bool {
297.     regex_fullmatch_checked(pattern, text).unwrap_or(false)
298. }
