300. /// `device_info.get_paths_to_platform_and_hwsku_dirs()` → `(platform_path, hwsku_path)`,
301. /// sourced via PyO3 from the SAME embedded interpreter the bridge starts (the reference
302. /// media/optics loaders import `sonic_py_common.device_info`). `None` if the import/call
303. /// fails (no platform → the caller degrades to "no settings file").
304. pub fn get_paths_to_platform_and_hwsku_dirs() -> Option<(String, String)> {
305.     use pyo3::prelude::*;
306.     Python::with_gil(|py| {
307.         let di = py.import_bound("sonic_py_common.device_info").ok()?;
308.         let tup = di.call_method0("get_paths_to_platform_and_hwsku_dirs").ok()?;
309.         let platform: String = tup.get_item(0).ok()?.extract().ok()?;
310.         let hwsku: String = tup.get_item(1).ok()?.extract().ok()?;
311.         Some((platform, hwsku))
312.     })
313. }
314. 
315. /// Load a SONiC platform settings JSON file (`media_settings.json` /
316. /// `optics_si_settings.json`), preferring the HWSKU dir over the platform dir — the
317. /// exact search order of `media_settings_parser.load_media_settings` /
318. /// `optics_si_parser.load_optics_si_settings`. Returns the parsed object, or an empty
319. /// object when no file exists / the paths can't be resolved / the JSON is malformed
320. /// (mirroring the reference `return {}`).
321. pub fn load_json_settings(filename: &str) -> serde_json::Value {
322.     let Some((platform_path, hwsku_path)) = get_paths_to_platform_and_hwsku_dirs() else {
323.         return serde_json::json!({});
324.     };
325.     let hwsku_file = std::path::Path::new(&hwsku_path).join(filename);
326.     let platform_file = std::path::Path::new(&platform_path).join(filename);
327.     let path = if hwsku_file.is_file() {
328.         hwsku_file
329.     } else if platform_file.is_file() {
330.         platform_file
331.     } else {
332.         return serde_json::json!({});
333.     };
334.     match std::fs::read_to_string(&path) {
335.         Ok(s) => serde_json::from_str(&s).unwrap_or_else(|e| {
336.             eprintln!("xcvrd-rs: parse {}: {e}", path.display());
337.             serde_json::json!({})
338.         }),
339.         Err(e) => {
340.             eprintln!("xcvrd-rs: read {}: {e}", path.display());
341.             serde_json::json!({})
342.         }
343.     }
344. }
