351.     // ← tests/test_xcvrd.py::test_wrapper_get_presence (HAL-seam adaptation)
352.     // The Python test patches platform_chassis.get_sfp(...).get_presence(); here the
353.     // caller already holds the SfpHandle, so we exercise the present/absent + error
354.     // -> false fallback directly over MockSfp.
355.     #[test]
356.     fn wrapper_get_presence_reads_handle_and_defaults_false() {
357.         let present = MockSfp::present();
358.         assert!(wrapper_get_presence(&present).unwrap());
359. 
360.         let absent = MockSfp::default();
361.         assert!(!wrapper_get_presence(&absent).unwrap());
362.     }
363. 
364.     // update_port_transceiver_status_table_sw writes exactly {status, error} and, on a
365.     // merging table, leaves any pre-existing cmis_state field intact.
366.     #[test]
367.     fn update_status_sw_sets_status_and_error() {
368.         let tbl = MockDbTable::new("TRANSCEIVER_STATUS_SW");
369.         update_port_transceiver_status_table_sw("Ethernet0", &tbl, "1", "N/A");
370.         assert_eq!(tbl.hget("Ethernet0", "status").as_deref(), Some("1"));
371.         assert_eq!(tbl.hget("Ethernet0", "error").as_deref(), Some("N/A"));
372.         assert_eq!(tbl.get_size_for_key("Ethernet0"), 2);
373.     }
