375.     // del_port_sfp_dom_info_from_db deletes the port's row from every supplied table.
376.     #[test]
377.     fn del_port_sfp_dom_info_removes_rows() {
378.         let a = MockDbTable::new("TRANSCEIVER_INFO");
379.         let b = MockDbTable::new("TRANSCEIVER_DOM_SENSOR");
380.         a.hset("Ethernet0", "type", "QSFP-DD");
381.         b.hset("Ethernet0", "temperature", "22.75");
382.         del_port_sfp_dom_info_from_db("Ethernet0", &[&a as &dyn DbTable, &b as &dyn DbTable]);
383.         assert_eq!(a.get_size_for_key("Ethernet0"), 0);
384.         assert_eq!(b.get_size_for_key("Ethernet0"), 0);
385.     }
386. 
387.     // ← tests/test_xcvrd.py::test_get_cmis_state_from_state_db
388.     #[test]
389.     fn test_get_cmis_state_from_state_db() {
390.         let tbl = MockDbTable::new("TRANSCEIVER_STATUS_SW");
391.         // found=True, state=INSERTED → INSERTED
392.         tbl.hset("Ethernet0", "cmis_state", CMIS_STATE_INSERTED);
393.         assert_eq!(get_cmis_state_from_state_db("Ethernet0", &tbl), CMIS_STATE_INSERTED);
394.         // found=False (field absent) → UNKNOWN
395.         assert_eq!(get_cmis_state_from_state_db("Ethernet8", &tbl), CMIS_STATE_UNKNOWN);
396.     }
397. 
398.     // ← tests/test_xcvrd.py::test_CmisManagerTask_get_cmis_host_lanes_mask (app-select half)
399.     // get_interface_speed maps the CMIS host-electrical-interface names to speeds, and
400.     // get_cmis_application picks the app whose advertised host_lane_count + speed match.
401.     #[test]
402.     fn test_get_cmis_application() {
403.         assert_eq!(get_interface_speed("400GAUI-8 C2M (Annex 120E)"), 400_000);
404.         assert_eq!(get_interface_speed("CAUI-4 C2M (Annex 83E)"), 100_000);
405.         assert_eq!(get_interface_speed("50GAUI-1 C2M"), 50_000);
406.         assert_eq!(get_interface_speed("XLAUI"), 40_000);
407.         assert_eq!(get_interface_speed("nonsense"), 0);
408. 
409.         let advert = serde_json::json!({
410.             "1": {"host_electrical_interface_id": "400GAUI-8 C2M (Annex 120E)", "host_lane_count": 8, "host_lane_assignment_options": 1},
411.             "2": {"host_electrical_interface_id": "CAUI-4 C2M (Annex 83E)", "host_lane_count": 4, "host_lane_assignment_options": 17},
412.             "3": {"host_electrical_interface_id": "50GAUI-1 C2M", "host_lane_count": 1, "host_lane_assignment_options": 255}
413.         });
414.         // 8-lane 400G → app 1; 4-lane 100G → app 2; 1-lane 50G → app 3.
415.         assert_eq!(get_cmis_application(8, 400_000, &advert), Some(1));
416.         assert_eq!(get_cmis_application(4, 100_000, &advert), Some(2));
417.         assert_eq!(get_cmis_application(1, 50_000, &advert), Some(3));
418.         // No match / degenerate inputs → None.
419.         assert_eq!(get_cmis_application(1, 200_000, &advert), None);
420.         assert_eq!(get_cmis_application(0, 400_000, &advert), None);
421.         assert_eq!(get_cmis_application(8, 0, &advert), None);
422.     }
423. }
