263.                     let tb = rb.trim_start_matches('0');
264.                     let ord = ta.len().cmp(&tb.len()).then_with(|| ta.cmp(tb));
265.                     if ord != Ordering::Equal {
266.                         return ord;
267.                     }
268.                 } else {
269.                     let ord = ca.cmp(&cb);
270.                     if ord != Ordering::Equal {
271.                         return ord;
272.                     }
273.                     ai.next();
274.                     bi.next();
275.                 }
276.             }
277.         }
278.     }
279. }
