1. //! `xcvrd.py :: SfpStateUpdateTask` → the presence/identity + plug/unplug/error state
2. //! machine (analysis §1.3, §3.2).
3. //!
4. //! A 3-state machine (`STATE_INIT`/`STATE_NORMAL`/`STATE_EXIT`) driven by
5. //! `get_change_event`: on a `NORMAL_EVENT` it dispatches per physical-port code —
6. //! `"1"` insert (publish INFO + `STATUS_SW`), `"0"` remove (delete every
7. //! `TRANSCEIVER_*` row), else an error bitmap (decode → `STATUS_SW.error`).
8. //!
9. //! M1 implements presence/identity/retry/stale + the error branch (which only needs
10. //! the three trivial `sfp_status_helper` bit decoders). DOM/VDM threshold posting +
11. //! media-setting notify (the `rc != SFP_EEPROM_NOT_READY` follow-ups) land with M4/M9.
12. //! A plug-out drops the plugin's cached `xcvr_api` (`remove_xcvr_api`, M5) so a re-insert
13. //! re-reads the module EEPROM fresh; the NPU-Si `state_port` sync lands with M9/M11.
14. //! `cmis_state` is owned exclusively by [`crate::cmis::cmis_manager_task::CmisManagerTask`]
15. //! (mirroring `cmis_manager_task.py`, the sole writer in the reference) — this task never
16. //! writes it, so a boot/plug status update cannot clobber an in-progress CMIS bring-up.
17. //!
18. //! Testability seam: the reference `task_worker` calls `self.init()` at entry; here
19. //! [`SfpStateUpdateTask::init`] is a separate method the production `serve()` runs
20. //! before [`SfpStateUpdateTask::task_worker`], so the state-machine loop can be unit
21. //! tested in isolation by injecting crafted change events through the mock HAL.
22. #![allow(dead_code, unused_variables, unused_imports)]
23. 
24. use std::collections::{BTreeMap, BTreeSet};
25. use std::sync::atomic::{AtomicBool, Ordering};
26. use std::sync::Arc;
27. use std::time::{Duration, Instant};
28. 
29. use serde_json::{json, Value};
30. 
31. use crate::cmis::cmis_api::{BridgeCmisApi, CmisApi};
32. use crate::cmis::cmis_manager_task::CMIS_MODULE_TYPES;
33. use crate::db::DbTable;
34. use crate::dom::utilities::db::DbCache;
35. use crate::dom::utilities::dom_sensor::DomDbUtils;
36. use crate::dom::utilities::vdm::{VdmDbUtils, VdmThresholdCache};
37. use crate::hal::Hal;
38. use crate::xcvrd::{build_transceiver_dict, post_port_sfp_info_to_db, SFP_EEPROM_NOT_READY};
39. use crate::xcvrd_utilities::common::{
40.     del_port_sfp_dom_info_from_db, update_port_transceiver_status_table_sw, wrapper_get_presence,
41. };
42. use crate::xcvrd_utilities::media_settings_parser::{
43.     self, get_media_settings_key, MediaSettingsKey, PortMediaResolver,
44. };
45. use crate::xcvrd_utilities::port_event_helper::{PortChangeEvent, PortMapping};
46. use crate::xcvrd_utilities::sfp_status_helper::{
47.     fetch_generic_error_description, has_vendor_specific_error, is_error_block_eeprom_reading,
48.     SFP_STATUS_INSERTED, SFP_STATUS_REMOVED,
