52.     VDM_THRESHOLD_TYPES,
53. };
54. 
55. // --- event codes (xcvrd.py) -------------------------------------------------------
56. pub const EVENT_ON_ALL_SFP: &str = "-1";
57. pub const SYSTEM_NOT_READY: &str = "system_not_ready";
58. pub const SYSTEM_BECOME_READY: &str = "system_become_ready";
59. pub const SYSTEM_FAIL: &str = "system_fail";
60. pub const NORMAL_EVENT: &str = "normal";
61. 
62. // --- state machine constants (xcvrd.py) -------------------------------------------
63. const STATE_INIT: u8 = 0;
64. const STATE_NORMAL: u8 = 1;
65. const STATE_EXIT: u8 = 2;
66. const RETRY_PERIOD_FOR_SYSTEM_READY_MSECS: u64 = 5000;
67. const RETRY_TIMES_FOR_SYSTEM_READY: u32 = 24;
68. const RETRY_PERIOD_FOR_SYSTEM_FAIL_MSECS: u64 = 5000;
69. const RETRY_TIMES_FOR_SYSTEM_FAIL: u32 = 24;
70. const STATE_MACHINE_UPDATE_PERIOD_MSECS: u64 = 60000;
71. const SFP_INSERT_EVENT_POLL_PERIOD_MSECS: u64 = 1000;
72. 
73. /// The change-event outcomes that drive the `STATE_INIT/NORMAL/EXIT` machine.
74. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
75. pub enum SystemEvent {
76.     SystemNotReady,
77.     SystemBecomeReady,
78.     Normal,
79.     SystemFail,
80. }
81. 
82. impl SystemEvent {
83.     pub fn as_str(&self) -> &'static str {
84.         match self {
85.             SystemEvent::SystemNotReady => SYSTEM_NOT_READY,
86.             SystemEvent::SystemBecomeReady => SYSTEM_BECOME_READY,
87.             SystemEvent::Normal => NORMAL_EVENT,
88.             SystemEvent::SystemFail => SYSTEM_FAIL,
89.         }
90.     }
91. 
92.     /// Parse a system-level `EVENT_ON_ALL_SFP` payload back into an event.
93.     pub fn from_code(code: &str) -> SystemEvent {
94.         match code {
95.             SYSTEM_NOT_READY => SystemEvent::SystemNotReady,
96.             SYSTEM_BECOME_READY => SystemEvent::SystemBecomeReady,
97.             NORMAL_EVENT => SystemEvent::Normal,
98.             _ => SystemEvent::SystemFail,
99.         }
100.     }
101. }
102. 
103. /// `SfpStateUpdateTask` — presence/identity engine + change-event state machine.
104. pub struct SfpStateUpdateTask {
105.     namespaces: Vec<String>,
