633. fn sleep_compensation(time_start: Instant, period_ms: u64) {
634.     let period = Duration::from_millis(period_ms);
635.     let elapsed = time_start.elapsed();
636.     if elapsed < period {
637.         std::thread::sleep(period - elapsed);
638.     }
639. }
