642. /// publish INFO (one immediate retry after a settle delay). `cmis_state` is deliberately
643. /// left to the `CmisManagerTask` (its sole owner, per xcvrd.py) so this insert path cannot
644. /// race/clobber an in-progress CMIS datapath bring-up. A still-unready EEPROM joins the
645. /// retry set.
646. fn handle_sfp_insert(
647.     logical_port: &str,
648.     port_mapping: &PortMapping,
649.     hal: &dyn Hal,
650.     th: &XcvrTableHelper,
651.     asic_index: usize,
