659.         logical_port,
660.         th.get_status_sw_tbl(asic_index),
661.         SFP_STATUS_INSERTED,
662.         "N/A",
663.     );
664. 
665.     let intf_tbl = th.get_intf_tbl(asic_index);
666.     let mut rc = post_port_sfp_info_to_db(logical_port, port_mapping, intf_tbl, hal);
667.     if rc == SFP_EEPROM_NOT_READY {
668.         if !time_for_sfp_ready.is_zero() {
669.             std::thread::sleep(time_for_sfp_ready);
670.         }
671.         rc = post_port_sfp_info_to_db(logical_port, port_mapping, intf_tbl, hal);
672.         if rc == SFP_EEPROM_NOT_READY {
