     pub fn is_npu_si_settings_update_required(&self, lport: &str, port_mapping: &PortMapping) -> bool {
         let val = self.get_state_db_port_table_val_by_key(lport, Some(port_mapping), NPU_SI_SETTINGS_SYNC_STATUS_KEY);
