176.     pub fn mapping_event_from_change_event(
177.         &self,
178.         status: bool,
179.         port_dict: &mut BTreeMap<String, String>,
180.     ) -> SystemEvent {
181.         if status {
182.             if !port_dict.is_empty() {
183.                 SystemEvent::Normal
184.             } else {
185.                 port_dict.insert(EVENT_ON_ALL_SFP.to_string(), SYSTEM_BECOME_READY.to_string());
186.                 SystemEvent::SystemBecomeReady
187.             }
188.         } else if let Some(code) = port_dict.get(EVENT_ON_ALL_SFP) {
189.             SystemEvent::from_code(code)
190.         } else {
191.             port_dict.insert(EVENT_ON_ALL_SFP.to_string(), SYSTEM_FAIL.to_string());
192.             SystemEvent::SystemFail
193.         }
194.     }
195. 
196.     /// `_post_port_sfp_info_and_dom_thr_to_db_once` — boot-time INFO publish (DOM/VDM
197.     /// thresholds land with M4). Records ports whose EEPROM was not ready into the
198.     /// retry set. Honors the stop flag between ports.
199.     pub fn post_port_sfp_info_and_dom_thr_to_db_once(&mut self, stop: &AtomicBool) {
200.         let hal = self.hal.clone();
201.         let th = self.table_helper.clone();
202.         // Pre-fetch the per-ASIC warm-start status once (xcvrd.py:314-317): a warm reboot
203.         // suppresses the boot media SI notify so an in-service datapath is not flapped.
204.         let warm_start: Vec<bool> = (0..self.namespaces.len())
205.             .map(|a| th.is_syncd_warm_restore_complete(a))
206.             .collect();
207.         let mut retry_eeprom_set = BTreeSet::new();
208.         for logical_port_name in self.port_mapping.logical_port_list() {
209.             if stop.load(Ordering::Relaxed) {
210.                 break;
211.             }
212.             let Some(asic_index) = self.port_mapping.get_asic_id_for_logical_port(logical_port_name)
213.             else {
214.                 continue;
215.             };
216.             let rc = post_port_sfp_info_to_db(
217.                 logical_port_name,
218.                 &self.port_mapping,
219.                 th.get_intf_tbl(asic_index),
220.                 hal.as_ref(),
221.             );
222.             if rc == SFP_EEPROM_NOT_READY {
223.                 retry_eeprom_set.insert(logical_port_name.to_string());
224.             } else if !warm_start.get(asic_index).copied().unwrap_or(false) {
225.                 // Publish the ASIC-side media SI + stamp NPU_SI_SETTINGS_NOTIFIED for a
226.                 // module already present at boot (xcvrd.py:336-338).
227.                 notify_media_setting_for_logical_port(
228.                     logical_port_name,
229.                     &self.port_mapping,
230.                     hal.as_ref(),
231.                     th.as_ref(),
232.                     &self.media_settings,
233.                 );
234.             }
235.         }
236.         self.retry_eeprom_set = retry_eeprom_set;
