13. // --- SFP_STATUS_* -----------------------------------------------------------------
14. pub const SFP_STATUS_REMOVED: &str = "0";
15. pub const SFP_STATUS_INSERTED: &str = "1";
16. 
17. // --- error masks (sfp_status_helper.py) -------------------------------------------
18. pub const SFP_ERRORS_BLOCKING_MASK: u32 = 0x02;
19. pub const SFP_ERRORS_GENERIC_MASK: u32 = 0x0000_FFFE;
20. pub const SFP_ERRORS_VENDOR_SPECIFIC_MASK: u32 = 0xFFFF_0000;
21. 
22. /// The blocking sentinel string `detect_port_in_error_status` looks for in
23. /// `TRANSCEIVER_STATUS_SW.error`.
24. pub const SFP_ERROR_DESCRIPTION_BLOCKING: &str = "Blocking EEPROM from being read";
25. 
26. /// `SfpBase.SFP_ERROR_BIT_TO_DESCRIPTION_DICT` (bit → description). Real data — the
27. /// e2e error assertions read these exact strings.
28. ///
29. /// TODO(Translator, M4): confirm the full bit set against the emulator + upstream
30. /// `SfpBase` and extend as error scenarios are exercised.
31. pub const SFP_ERROR_BIT_TO_DESCRIPTION: &[(u32, &str)] = &[
32.     (0x0002, "Blocking EEPROM from being read"),
33.     (0x0004, "Power budget exceeded"),
34.     (0x0008, "Bus stuck (I2C data or clock shorted)"),
35.     (0x0010, "Bad or unsupported EEPROM"),
36.     (0x0020, "Unsupported cable"),
37.     (0x0040, "High temperature"),
38.     (0x0080, "Bad cable (module/cable is shorted)"),
39. ];
40. 
41. /// `is_error_block_eeprom_reading(error_bits)` — does this bitmap block the EEPROM read
42. /// (→ delete DOM rows but keep TRANSCEIVER_INFO)?
43. pub fn is_error_block_eeprom_reading(error_bits: u32) -> bool {
44.     (error_bits & SFP_ERRORS_BLOCKING_MASK) != 0
45. }
46. 
47. /// `has_vendor_specific_error(error_bits)`.
48. pub fn has_vendor_specific_error(error_bits: u32) -> bool {
49.     (error_bits & SFP_ERRORS_VENDOR_SPECIFIC_MASK) != 0
50. }
51. 
52. /// `fetch_generic_error_description(error_bits)` → the `|`-joinable description list.
53. ///
54. /// Mirrors `sfp_status_helper.fetch_generic_error_description`: mask to the generic
55. /// bits, then append each matching description in `SFP_ERROR_BIT_TO_DESCRIPTION` order
56. /// (the same insertion order as `SfpBase.SFP_ERROR_BIT_TO_DESCRIPTION_DICT`), so the
57. /// joined string is byte-identical to the reference (`test_status_error.py`).
58. pub fn fetch_generic_error_description(error_bits: u32) -> Vec<String> {
59.     let generic_error_bits = error_bits & SFP_ERRORS_GENERIC_MASK;
60.     let mut descriptions = Vec::new();
61.     if generic_error_bits != 0 {
62.         for (error_bit, description) in SFP_ERROR_BIT_TO_DESCRIPTION {
63.             if error_bit & generic_error_bits != 0 {
64.                 descriptions.push((*description).to_string());
65.             }
66.         }
67.     }
68.     descriptions
69. }
