414.     /// `on_add_logical_port` (xcvrd.py:770) — a CONFIG_DB logical port was added.
415.     ///
416.     /// Reseeds `PORT_TABLE.NPU_SI_SETTINGS_SYNC_STATUS` to the default (a freshly added
417.     /// port must re-notify its media SI), then repopulates the port's DB rows from the
418.     /// module. Three cases mirror the reference: (1) SFP present + no blocking error →
419.     /// publish `TRANSCEIVER_INFO` + DOM/VDM thresholds + media-SI notify (a still-unready
420.     /// EEPROM joins the retry set); (2) present with a blocking SFP error → only the
421.     /// decoded `TRANSCEIVER_STATUS_SW.error`; (3) absent → mark `REMOVED`. In every case
422.     /// the final `update_port_transceiver_status_table_sw` writes the resolved
423.     /// `{status, error}`. `cmis_state` is left to the `CmisManagerTask` (its sole owner).
424.     pub fn on_add_logical_port(&mut self, port_change_event: &PortChangeEvent, stop: &AtomicBool) {
425.         let asic_index = port_change_event.asic_id;
426.         let hal = self.hal.clone();
427.         let th = self.table_helper.clone();
428.         let status_sw_tbl = th.get_status_sw_tbl(asic_index);
429.         let int_tbl = th.get_intf_tbl(asic_index);
430.         let port_name = port_change_event.port_name.clone();
431. 
432.         // Initialize the NPU_SI_SETTINGS_SYNC_STATUS to the default value (xcvrd.py:788-796).
433.         th.get_state_port_tbl(asic_index).set(
434.             &port_name,
435.             &[(
436.                 NPU_SI_SETTINGS_SYNC_STATUS_KEY.to_string(),
437.                 NPU_SI_SETTINGS_DEFAULT_VALUE.to_string(),
438.             )],
439.         );
440. 
441.         let mut error_description = "N/A".to_string();
442.         let mut status: Option<String> = None;
443.         let mut read_eeprom = true;
444. 
445.         // A cached SFP error for this physical port sets the status/error and can block
446.         // the EEPROM read (xcvrd.py:801-819). The Rust `sfp_error_dict` is keyed by the
447.         // physical-port string and stores only the error value; the per-port vendor error
448.         // map is unavailable here, so a vendor-specific bit falls back to the HAL error
449.         // description exactly like the reference's empty-`error_dict` branch.
450.         if let Some(phys_idx) = port_change_event.physical_port {
451.             if let Some(value) = self.sfp_error_dict.get(&phys_idx.to_string()).cloned() {
452.                 status = Some(value.clone());
453.                 if let Ok(error_bits) = value.parse::<u32>() {
454.                     let mut error_descriptions = fetch_generic_error_description(error_bits);
455.                     if has_vendor_specific_error(error_bits) {
456.                         let vendor_specific = hal
457.                             .sfp(phys_idx)
458.                             .ok()
459.                             .and_then(|s| s.get_error_description().ok().flatten())
460.                             .unwrap_or_default();
461.                         error_descriptions.push(vendor_specific);
462.                     }
463.                     error_description = error_descriptions.join("|");
464.                     if is_error_block_eeprom_reading(error_bits) {
465.                         read_eeprom = false;
466.                     }
467.                 }
468.             }
469.         }
470. 
471.         let present = port_change_event
472.             .physical_port
473.             .map(|p| {
474.                 hal.sfp(p)
475.                     .ok()
476.                     .map(|s| wrapper_get_presence(s.as_ref()).unwrap_or(false))
477.                     .unwrap_or(false)
478.             })
479.             .unwrap_or(false);
480. 
481.         if present && read_eeprom {
482.             if status.is_none() {
483.                 status = Some(SFP_STATUS_INSERTED.to_string());
484.             }
485.             let rc = post_port_sfp_info_to_db(&port_name, &self.port_mapping, int_tbl, hal.as_ref());
486.             if rc == SFP_EEPROM_NOT_READY {
487.                 self.retry_eeprom_set.insert(port_name.clone());
488.             } else {
489.                 DomDbUtils::new().post_port_dom_thresholds_to_db(
490.                     stop,
491.                     &port_name,
492.                     &self.port_mapping,
493.                     th.get_dom_threshold_tbl(asic_index),
494.                     hal.as_ref(),
495.                     None,
496.                 );
497.                 VdmDbUtils::new().post_port_vdm_thresholds_to_db(
498.                     stop,
499.                     &port_name,
500.                     &self.port_mapping,
501.                     hal.as_ref(),
502.                     th.as_ref(),
503.                     None,
504.                 );
505.                 notify_media_setting_for_logical_port(
506.                     &port_name,
507.                     &self.port_mapping,
508.                     hal.as_ref(),
509.                     th.as_ref(),
510.                     &self.media_settings,
