     #[test]
     fn on_remove_logical_port_deletes_whole_table_set() {
         let hal = MockHal::with_sfps(vec![MockSfp::present().with_info(cmis_info())]);
         let mut t = task(hal, port_mapping(&[("Ethernet0", 0)]));
         let th = t.table_helper.clone();
